class Solution {
public:
    int maxSumAfterPartitioning(vector<int>& arr, int k) {
        int n = arr.size();
        vector<int> dp(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            int top = 0;
            for (int len = 1; len <= k && len <= i; len++) {
                top = max(top, arr[i - len]);
                dp[i] = max(dp[i], dp[i - len] + top * len);
            }
        }
        return dp[n];
    }
};
